mapper.select:
SELECT id, user_id, title, status, last_active_at, deleted_at, created_at, updated_at
FROM sessions
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'active'

SELECT id, user_id, title, status, last_active_at, deleted_at, created_at, updated_at
FROM sessions
WHERE user_id = #{userId}
  AND status = 'active'

  AND (last_active_at < #{beforeActiveAt}
       OR (last_active_at = #{beforeActiveAt} AND id < #{beforeId}))

ORDER BY last_active_at DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE sessions
SET title = #{title}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'active'

UPDATE sessions
SET status = 'archived',
    deleted_at = #{deletedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'active'
